LEGACY_RECORDS = [{'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/capacity.csv', 'values': {'PlatformId': '1', 'Capacity': '1336'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/capacity.csv', 'values': {'PlatformId': '2', 'Capacity': '1754'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/capacity.csv', 'values': {'PlatformId': '3', 'Capacity': '1617'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/capacity.csv', 'values': {'PlatformId': '4', 'Capacity': '1119'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/capacity.csv', 'values': {'PlatformId': '5', 'Capacity': '1410'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/capacity.csv', 'values': {'PlatformId': '6', 'Capacity': '627'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/capacity.csv', 'values': {'PlatformId': '7', 'Capacity': '748'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/capacity.csv', 'values': {'PlatformId': '8', 'Capacity': '1540'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/capacity.csv', 'values': {'PlatformId': '9', 'Capacity': '1292'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/capacity.csv', 'values': {'PlatformId': '10', 'Capacity': '1138'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/products.csv', 'values': {'ProductName': 'Racing', 'Value': '28', 'Weight': '393'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/products.csv', 'values': {'ProductName': 'Sports', 'Value': '69', 'Weight': '195'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/products.csv', 'values': {'ProductName': 'Action', 'Value': '20', 'Weight': '192'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/products.csv', 'values': {'ProductName': 'Adventure', 'Value': '62', 'Weight': '155'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/products.csv', 'values': {'ProductName': 'RPG', 'Value': '58', 'Weight': '500'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/products.csv', 'values': {'ProductName': 'Shooter', 'Value': '11', 'Weight': '156'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/products.csv', 'values': {'ProductName': 'Strategy', 'Value': '73', 'Weight': '317'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/products.csv', 'values': {'ProductName': 'Simulation', 'Value': '43', 'Weight': '694'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/products.csv', 'values': {'ProductName': 'Puzzle', 'Value': '28', 'Weight': '751'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/products.csv', 'values': {'ProductName': 'Fighting', 'Value': '57', 'Weight': '467'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/products.csv', 'values': {'ProductName': 'Platformer', 'Value': '92', 'Weight': '796'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/products.csv', 'values': {'ProductName': 'Survival', 'Value': '66', 'Weight': '146'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/products.csv', 'values': {'ProductName': 'Horror', 'Value': '14', 'Weight': '269'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/products.csv', 'values': {'ProductName': 'Sandbox', 'Value': '49', 'Weight': '246'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/RA_testing/RA13/VideoGameSales1/products.csv', 'values': {'ProductName': 'MMO', 'Value': '12', 'Weight': '652'}}]
from gurobipy import Model, GRB, quicksum
platform_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
platform_ids = []
capacities = {}
for rec in platform_records:
    pid = rec['values']['PlatformId']
    cap = rec['values']['Capacity']
    platform_ids.append(pid)
    capacities[pid] = int(cap)
product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
genres = []
values = {}
weights = {}
for rec in product_records:
    genre = rec['values']['ProductName']
    val = rec['values']['Value']
    wt = rec['values']['Weight']
    genres.append(genre)
    values[genre] = int(val)
    weights[genre] = int(wt)
if len(platform_ids) != 10:
    raise ValueError('Expected 10 platforms, got %d' % len(platform_ids))
if len(genres) != 15:
    raise ValueError('Expected 15 genres, got %d' % len(genres))
for pid in platform_ids:
    if pid not in capacities:
        raise ValueError(f'Missing capacity for platform {pid}')
for genre in genres:
    if genre not in values or genre not in weights:
        raise ValueError(f'Missing value or weight for genre {genre}')
m = Model()
m.Params.MIPGap = 0.0001
x_vars = m.addVars(platform_ids, genres, vtype=GRB.INTEGER, lb=0, name='')
m.setObjective(quicksum((values[genre] * x_vars[pid, genre] for pid in platform_ids for genre in genres)), GRB.MAXIMIZE)
for pid in platform_ids:
    m.addConstr(quicksum((weights[genre] * x_vars[pid, genre] for genre in genres)) <= capacities[pid], name=f'cap_{pid}')
m.optimize()
if m.Status == GRB.OPTIMAL:
    print('ObjVal', m.ObjVal)
    for v in m.getVars():
        print(v.VarName, v.X)
else:
    print('Solver status:', m.Status)